<script>
 import {onMount,tick} from 'svelte';
 import WindowControls from './WindowControls.svelte';
 import {grapherWindow,grapherCapabilities} from './grapher-state.js';
 import {grapherMenus} from './grapher-menus.js';
 import {GRAPHER_TEMPLATES,grapherParameter} from './grapher-engine.js';
 import {createGrapherNativeView,drawGrapherCanvas} from './grapher-native-view.js';
 import './grapher.css';
 let {state: grapherState,profile,window:actualWindow=null,windowId:providedId=null,execute,registerView,sceneTime=0,available=true,active=true,controls={}}=$props();
 const windowId=$derived(providedId??actualWindow?.id),session=$derived(grapherWindow(grapherState,windowId)),cap=$derived(grapherCapabilities(profile));
 const selected=$derived(session?.document.equations.find(e=>e.id===session.selectedId)),menus=$derived(grapherMenus({state: grapherState,profile,windowId})),menu=$derived(menus.find(m=>m.id===session?.menu));
 let root=$state(null),canvas=$state(null),facade=$state(null),message=$state(''),draft=$state(''),drag=$state(null);
 let originalState,originalProfile,originalId,originalSession,originalWindow,retired=false;
 const current=()=>!retired&&!!session&&root?.isConnected===true&&grapherState===originalState&&profile===originalProfile&&windowId===originalId&&actualWindow===originalWindow&&session===originalSession&&(!actualWindow||actualWindow.id===windowId&&actualWindow.appId==='grapher');
 async function command(suffix,payload={}){if(!current()||!available||!active)return;const response=await execute(`grapher.${suffix}`,{windowId},payload);if(current())message=response?.status==='applied'?'':response?.error?.message??'The actual graph operation is unavailable.';return response;}
 async function menuAction(item){if(!item.enabled||!item.request||!current())return;const result=await execute(item.request.command,item.request.target,item.request.payload);if(current()){message=result?.status==='applied'?'':result?.error?.message??'Menu operation unavailable.';if(result?.status==='applied')command('menu',{menu:null});}}
 function updateRange(axis,key,value){if(!session)return;command('range',{...session.document.range,[axis+key]:Number(value)});}
 function edit(event){event.preventDefault();if(selected)command('equation.edit',{equationId:selected.id,expression:draft});}
 function keyboard(event){if(!available||!active||!current())return;const modifier=cap.windows?event.ctrlKey:event.metaKey;if(modifier){const suffix={s:'save',o:'open',n:'window.new',p:'print',w:'window.close'}[event.key.toLowerCase()];if(suffix){event.preventDefault();command(suffix,event.key.toLowerCase()==='s'&&event.shiftKey?{saveAs:true}:{});}}else if(event.key==='Escape')command('menu',{menu:null});else if(event.key==='Delete'&&!event.target.matches('input,textarea,select')&&selected){event.preventDefault();command('equation.delete',{equationId:selected.id});}}
 function pointerDown(event){if(!current()||!available||!active)return;canvas.setPointerCapture(event.pointerId);drag={x:event.clientX,y:event.clientY,id:event.pointerId};}
 function pointerUp(event){if(!drag||drag.id!==event.pointerId||!current())return;const bounds=canvas.getBoundingClientRect(),dx=event.clientX-drag.x,dy=event.clientY-drag.y;drag=null;if(session.document.dimension===3)command('settings',{rotation:Math.max(-360,Math.min(360,session.document.rotation+dx*.5))});else command('pan',{x:-dx/bounds.width*(session.document.range.xMax-session.document.range.xMin),y:dy/bounds.height*(session.document.range.yMax-session.document.range.yMin)});}
 async function drop(event){event.preventDefault();let id=event.dataTransfer?.getData('application/x-jesteros-file-id');if(!id){try{id=JSON.parse(event.dataTransfer?.getData('application/x-jesteros-file-ids')||'[]')[0];}catch{}}if(typeof id==='string'&&id)await command('open',{fileId:id});}
 $effect(()=>{draft=selected?.expression??'';});
 $effect(()=>{const document=session?.document,time=sceneTime;JSON.stringify(document);if(canvas&&document)drawGrapherCanvas(canvas,document,time);});
 onMount(()=>{originalState=grapherState;originalProfile=profile;originalId=windowId;originalSession=session;originalWindow=actualWindow;facade=createGrapherNativeView({getRoot:()=>root,getCanvas:()=>canvas,getState:()=>grapherState,getProfile:()=>profile,getTime:()=>sceneTime,windowId,available:()=>current()&&available&&active,tick});registerView?.(windowId,facade);return()=>{retired=true;facade.destroy();registerView?.(originalId,null,facade);};});
</script>
<section bind:this={root} class="grapher-app" class:classic={cap.classic} class:windows={cap.windows} class:golden={cap.golden} data-grapher-window-id={windowId} data-profile={typeof profile==='string'?profile:profile.id} role="region" aria-label={cap.label} tabindex="0" onkeydown={keyboard} ondragover={event=>event.preventDefault()} ondrop={drop}>
 {#if session}
 <header class="grapher-titlebar">
 {#if !cap.windows}<WindowControls active={active} onclose={()=>command('window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} fullScreen={controls.fullScreen} zoomed={controls.zoomed}/>{/if}
 <strong>{session.document.title}{session.dirty?' — Edited':''}</strong><span class="grapher-title-label">{cap.label}</span>
 </header>
 <nav class="grapher-menu-strip" aria-label="Application menus">{#each menus.filter(m=>m.id!=='grapher') as group}<button data-grapher-control={`menu:${group.id}`} aria-expanded={session.menu===group.id} onclick={()=>command('menu',{menu:session.menu===group.id?null:group.id})}>{group.label}</button>{/each}</nav>
 {#if menu}<div class="grapher-menu" role="menu">{#each menu.children as item}<button role="menuitem" data-grapher-control={`menuitem:${item.id}`} disabled={!item.enabled} onclick={()=>menuAction(item)}>{item.checked?'✓ ':''}{item.label}<kbd>{item.shortcut??''}</kbd></button>{/each}</div>{/if}
 <div class="grapher-toolbar" inert={!available||!active}>
 <button data-grapher-control="zoom-in" onclick={()=>command('zoom',{factor:1.5})}><span>⊕</span>Zoom In</button><button data-grapher-control="zoom-out" onclick={()=>command('zoom',{factor:1/1.5})}><span>⊖</span>Zoom Out</button><button data-grapher-control="origin" onclick={()=>command('range',{xMin:-10,xMax:10,yMin:-10,yMax:10,zMin:-2,zMax:2})}><span>⊞</span>Center Origin</button>
 <details class="grapher-templates"><summary data-grapher-control="templates">New Graph</summary>{#each Object.entries(GRAPHER_TEMPLATES) as [id,template]}<button data-grapher-control={`template:${id}`} onclick={()=>command('window.new',{template:id})}>{template.dimension}D · {id}</button>{/each}</details>
 <button data-grapher-control="inspector" class="grapher-inspector-button" aria-pressed={session.inspector!=='none'} onclick={()=>command('inspector',{panel:session.inspector==='none'?'graph':'none'})}><span>ⓘ</span>Inspector</button>
 </div>
 {#if cap.windows||cap.golden}<p class="grapher-disclosure">{cap.disclosure}</p>{/if}
 <div class="grapher-workspace" inert={!available||!active}>
 <aside class="grapher-equations" aria-label="Equations list"><div class="grapher-equation-list">{#each session.document.equations as equation}<div class:selected={session.selectedId===equation.id} class="grapher-equation-row"><input type="checkbox" data-grapher-control={`visible:${equation.id}`} aria-label={`Show ${equation.expression}`} checked={equation.visible} onchange={event=>command('equation.style',{equationId:equation.id,visible:event.currentTarget.checked})}/><button data-grapher-control={`equation:${equation.id}`} onclick={()=>command('equation.select',{equationId:equation.id})} style:color={equation.color}>{equation.expression}</button></div>{/each}</div><footer><button data-grapher-control="add" aria-label="Add equation" onclick={()=>command('equation.add')}>+</button><button data-grapher-control="delete" aria-label="Delete equation" disabled={!selected} onclick={()=>command('equation.delete',{equationId:selected.id})}>−</button></footer></aside>
 <main class="grapher-graph"><form class="grapher-editor" onsubmit={edit}><input aria-label="Equation edit field" data-grapher-control="expression" spellcheck="false" maxlength="1024" bind:value={draft} disabled={!selected}/><button data-grapher-control="apply" disabled={!selected}>Plot</button><button type="button" data-grapher-control="equation-inspector" disabled={!selected} onclick={()=>command('inspector',{panel:'equation'})}>Σ⌄</button></form>
 <canvas bind:this={canvas} width="800" height="600" data-grapher-control="canvas" tabindex="0" aria-label={`Actual ${session.document.dimension}D graph canvas; drag to ${session.document.dimension===3?'rotate':'pan'}`} onpointerdown={pointerDown} onpointerup={pointerUp} onpointercancel={()=>drag=null}>Actual graph canvas requires a browser canvas renderer.</canvas>
 <div class="grapher-animation"><button data-grapher-control="play" aria-pressed={session.document.animation.playing} onclick={()=>command('animation',{playing:!session.document.animation.playing})}>{session.document.animation.playing?'Pause':'Animate a'}</button><label>a <input data-grapher-control="parameter" type="range" min={session.document.animation.min} max={session.document.animation.max} step="0.01" value={grapherParameter(session.document,sceneTime)} oninput={event=>command('animation',{playing:false,value:Number(event.currentTarget.value)})}/></label><output>{grapherParameter(session.document,sceneTime).toFixed(3)}</output></div>
 </main>
 {#if session.inspector!=='none'}<aside class="grapher-inspector"><header><strong>{session.inspector==='graph'?'Graph Inspector':'Equation Inspector'}</strong><button data-grapher-control="inspector-close" aria-label="Close inspector" onclick={()=>command('inspector',{panel:'none'})}>×</button></header>
 {#if session.inspector==='equation'&&selected}<label>Color<input data-grapher-control="color" type="color" value={selected.color} onchange={event=>command('equation.style',{equationId:selected.id,color:event.currentTarget.value})}/></label><label>Line width<input data-grapher-control="line-width" type="number" min="0.25" max="8" step="0.25" value={selected.width} onchange={event=>command('equation.style',{equationId:selected.id,width:Number(event.currentTarget.value)})}/></label><p>Explicit real scalar function. Radians; discontinuities split into separate curves.</p>{:else}
 <label>Title<input data-grapher-control="title" maxlength="128" value={session.document.title} onchange={event=>command('settings',{title:event.currentTarget.value})}/></label>
 {#each ['x','y',...(session.document.dimension===3?['z']:[])] as axis}<fieldset><legend>{axis} axis range</legend>{#each ['Min','Max'] as key}<label>{key}<input data-grapher-control={`range:${axis}${key}`} type="number" step="any" value={session.document.range[axis+key]} onchange={event=>updateRange(axis,key,event.currentTarget.value)}/></label>{/each}</fieldset>{/each}
 <label><input data-grapher-control="axes" type="checkbox" checked={session.document.axes} onchange={event=>command('settings',{axes:event.currentTarget.checked})}/>Axes</label><label><input data-grapher-control="grid" type="checkbox" checked={session.document.grid} disabled={session.document.dimension===3} onchange={event=>command('settings',{grid:event.currentTarget.checked})}/>Grid</label>
 {#if session.document.dimension===3}<label>Rotation<input data-grapher-control="rotation" type="range" min="-180" max="180" value={session.document.rotation} oninput={event=>command('settings',{rotation:Number(event.currentTarget.value)})}/></label>{/if}
 <fieldset><legend>Animation interval</legend>{#each ['min','max','speed'] as key}<label>{key}<input data-grapher-control={`animation:${key}`} type="number" step="any" value={session.document.animation[key]} onchange={event=>command('animation',{[key]:Number(event.currentTarget.value),playing:false})}/></label>{/each}</fieldset>
 {/if}<details><summary>Defined local math</summary><p>{cap.math} sin, cos, tan, inverse/hyperbolic functions, exp, ln, log, sqrt, abs, floor, ceil; pi and e. Unsupported implicit, vector and differential equations are rejected.</p><p>Animation follows authored scene time, not the host clock. Files save is explicit; not native macOS autosave.</p></details>
 </aside>{/if}
 </div><footer class="grapher-status" aria-live="polite">{message||session.status||`${session.document.dimension}D · ${cap.math}`}</footer>
 {:else}<p role="alert">The original canonical Grapher session is unavailable.</p>{/if}
</section>
